/* CRC32 (IEEE 802.3, reflected, polynomial 0xEDB88320).
 *
 * The lookup table in crc32_table.c was produced by a small generator
 * program that builds table[0][i] by running i through eight rounds of
 * the reflected polynomial division and then derives the remaining
 * seven slices with
 *
 *	table[n][i] = (table[n-1][i] >> 8) ^ table[0][table[n-1][i] & 0xFF]
 *
 * which is the usual slice-by-8 construction.
 *
 * The .xz format stores the plain final CRC value, so the caller passes
 * 0 as the initial value.  The one's complement that the standard CRC32
 * definition requires is applied internally at both ends.
 */

#include "check.h"

uint32_t xr_crc32(const uint8_t *buf, size_t size, uint32_t crc)
{
	crc = ~crc;

	/* Align to a four-byte boundary so that the main loop can read
	 * whole words without straddling anything expensive. */
	while (size > 0 && ((uintptr_t)buf & 3) != 0) {
		crc = xr_crc32_table[0][(crc ^ *buf++) & 0xFF] ^ (crc >> 8);
		--size;
	}

	while (size >= 8) {
		crc ^= xr_read32le(buf);
		const uint32_t tmp = xr_read32le(buf + 4);
		buf += 8;
		size -= 8;

		crc = xr_crc32_table[7][crc & 0xFF]
				^ xr_crc32_table[6][(crc >> 8) & 0xFF]
				^ xr_crc32_table[5][(crc >> 16) & 0xFF]
				^ xr_crc32_table[4][crc >> 24]
				^ xr_crc32_table[3][tmp & 0xFF]
				^ xr_crc32_table[2][(tmp >> 8) & 0xFF]
				^ xr_crc32_table[1][(tmp >> 16) & 0xFF]
				^ xr_crc32_table[0][tmp >> 24];
	}

	while (size > 0) {
		crc = xr_crc32_table[0][(crc ^ *buf++) & 0xFF] ^ (crc >> 8);
		--size;
	}

	return ~crc;
}

/* CRC64 (ECMA-182, reflected, polynomial 0xC96C5795D7870F42).
 *
 * crc64_table.c holds four slices built exactly like the CRC32 ones:
 * table[0][i] is the byte-at-a-time table and
 *
 *	table[n][i] = (table[n-1][i] >> 8) ^ table[0][table[n-1][i] & 0xFF]
 *
 * Four slices are enough to consume 32 bits of input per iteration,
 * which is the layout liblzma-compatible streams expect us to match in
 * results (the table layout itself is of course private).
 *
 * As with CRC32, .xz stores the plain final value and the caller starts
 * from 0; the complement is done internally.
 */

#include "check.h"

uint64_t xr_crc64(const uint8_t *buf, size_t size, uint64_t crc)
{
	crc = ~crc;

	while (size > 0 && ((uintptr_t)buf & 3) != 0) {
		crc = xr_crc64_table[0][(crc ^ *buf++) & 0xFF] ^ (crc >> 8);
		--size;
	}

	while (size >= 4) {
		const uint32_t tmp = (uint32_t)crc ^ xr_read32le(buf);
		buf += 4;
		size -= 4;

		crc = xr_crc64_table[3][tmp & 0xFF]
				^ xr_crc64_table[2][(tmp >> 8) & 0xFF]
				^ (crc >> 32)
				^ xr_crc64_table[1][(tmp >> 16) & 0xFF]
				^ xr_crc64_table[0][tmp >> 24];
	}

	while (size > 0) {
		crc = xr_crc64_table[0][(crc ^ *buf++) & 0xFF] ^ (crc >> 8);
		--size;
	}

	return ~crc;
}

