#define SMLSIG1(x) (rotr32(x, 17) ^ rotr32(x, 19) ^ ((x) >> 10))

static void sha256_transform(uint32_t state[8], const uint8_t block[64])
{
	uint32_t w[64];

	for (unsigned i = 0; i < 16; ++i)
		w[i] = xr_read32be(block + i * 4);

