{
	uint32_t *const state = check->state.sha256.state;
	size_t pos = (size_t)(check->state.sha256.size & 63);

	check->state.sha256.size += size;

	if (pos != 0) {
		size_t n = 64 - pos;
		if (n > size)
			n = size;

		memcpy(check->buffer.u8 + pos, buf, n);
		buf += n;
		size -= n;

		if (pos + n < 64)
			return;

		sha256_transform(state, check->buffer.u8);
	}

	while (size >= 64) {
		sha256_transform(state, buf);
		buf += 64;
		size -= 64;
