/* Independent bit-by-bit reference CRCs vs the table-driven ones. */
#include "check.h"
#include <stdio.h>

static uint32_t ref32(const uint8_t *b, size_t n)
{
	uint32_t c = ~UINT32_C(0);
	for (size_t i = 0; i < n; ++i) {
		c ^= b[i];
		for (int k = 0; k < 8; ++k)
			c = (c >> 1) ^ (UINT32_C(0xEDB88320) & -(c & 1));
	}
	return ~c;
}

static uint64_t ref64(const uint8_t *b, size_t n)
{
	uint64_t c = ~UINT64_C(0);
	for (size_t i = 0; i < n; ++i) {
		c ^= b[i];
		for (int k = 0; k < 8; ++k)
			c = (c >> 1) ^ (UINT64_C(0xC96C5795D7870F42)
					& -(c & 1));
	}
	return ~c;
}

int main(void)
{
	static uint8_t b[4096];
	uint32_t s = 12345;
	for (int trial = 0; trial < 2000; ++trial) {
		size_t n = (s = s * 1103515245u + 12345u) % sizeof(b);
		for (size_t i = 0; i < n; ++i)
			b[i] = (uint8_t)((s = s * 1103515245u + 12345u) >> 16);
		size_t off = trial % 8;
		if (off > n) off = 0;
		if (xr_crc32(b + off, n - off, 0) != ref32(b + off, n - off)) {
			printf("CRC32 MISMATCH n=%zu off=%zu\n", n, off);
			return 1;
		}
		if (xr_crc64(b + off, n - off, 0) != ref64(b + off, n - off)) {
			printf("CRC64 MISMATCH n=%zu off=%zu\n", n, off);
			return 1;
		}
	}
	/* Also every single-byte value, which pins down all 256 base
	 * table entries. */
	for (unsigned i = 0; i < 256; ++i) {
		uint8_t v = (uint8_t)i;
		if (xr_crc32(&v, 1, 0) != ref32(&v, 1)
				|| xr_crc64(&v, 1, 0) != ref64(&v, 1)) {
			printf("single-byte MISMATCH %u\n", i);
			return 1;
		}
	}
	printf("table-driven == bitwise reference: OK\n");
	return 0;
}
